{
  "candidates": [
    {
      "claimType": "phaseState",
      "statement": "该用户处于备考的启动或犹豫阶段，尚未进入实质性的执行状态。",
      "supportingRefs": [
        "o1",
        "o2"
      ],
      "alternativeExplanations": [
        "用户仅为他人（如子女或伴侣）购买教材并制定计划，自身并未参与备考。",
        "用户虽有强烈意愿但因外部不可抗力（如突发工作、家庭事务）导致计划搁置，而非个人习惯问题。"
      ],
      "verificationPlan": [
        {
          "op": "checkOwnership",
          "question": "确认 o1 中的考试教材是否由本人使用，还是代购给他人？"
        },
        {
          "op": "retrieveRelated",
          "question": "查询上月至今是否有其他与备考相关的行为记录（如报名缴费、购买文具、搜索真题），以判断是彻底停滞还是仅推迟了开始时间？"
        }
      ],
      "whatWouldChangeTheAnswer": "若证实教材为他人所用，则命题不成立；若发现后续有实质性学习行为，则命题应修正为‘备考进行中’。",
      "evidenceGrade": "线索",
      "action": "ask"
    }
  ]
}
